const body = $json.body || {};
const headers = $json.headers || {};
return [
  {
    json: {
      message: body.message ?? "",
      sessionId: body.sessionId ?? headers["x-session-id"] ?? "anon"
    }
  }
];

const raw = $json?.choices?.[0]?.message?.content ?? "";
let data;
try {
  data = JSON.parse(raw);
} catch (e) {
  data = {
    reply: raw || "Hola, soy Nico de Ferretería Ya. ¿Qué estás buscando?",
    product_query: null,
    followups: [],
    lead_capture: false
  };
}

return [
  {
    json: {
      ...data,
      sessionId: $node["Normalize Input"].json.sessionId,
      message: $node["Normalize Input"].json.message
    }
  }
];

const base = $node["Parse GPT JSON"].json;
const products = items.map(i => i.json).filter(p => p && p.permalink);

let reply = base.reply || "Listo.";

if (products.length) {
  const lines = products.slice(0, 3).map(p => `• ${p.name} → ${p.permalink}`);
  reply += `\n\nOpciones:\n${lines.join("\n")}`;
} else {
  const q = encodeURIComponent(base.product_query || "");
  reply += `\n\nNo vi una ficha exacta. Te dejo la búsqueda:\nhttps://ferreteriaya.com.co/?s=${q}&post_type=product`;
}

// Complemento simple (heurística rápida)
const qLower = (base.product_query || "").toLowerCase();
let comp = null;
if (qLower.includes("taladro") || qLower.includes("rotom") || qLower.includes("martillo")) comp = "brocas";
else if (qLower.includes("pint") || qLower.includes("rodillo")) comp = "brochas";
else if (qLower.includes("torn") || qLower.includes("chazo") || qLower.includes("taquete")) comp = "guantes";

if (comp) {
  const c = encodeURIComponent(comp);
  reply += `\n\nComplemento: ${comp} → https://ferreteriaya.com.co/?s=${c}&post_type=product`;
}

return [{
  json: {
    reply,
    followups: Array.isArray(base.followups) ? base.followups : [],
    sessionId: base.sessionId,
    lead_capture: !!base.lead_capture
  }
}];

